const PERMITS_API_BASE='https://7debzkoq7k.execute-api.us-east-2.amazonaws.com';
async function geocodePermitLocation(l){
 if(!l?.address)return false;
 const token=sessionStorage.getItem('sonomarzi.aws.id_token'),ctx=SuiteStore.remoteContext?.()||{};
 if(!token||!ctx.tenantId||!ctx.agencyId)throw Error('Choose an agency workspace and sign in before geocoding.');
 const res=await fetch(PERMITS_API_BASE+'/permits/geocode',{method:'POST',headers:{Authorization:'Bearer '+token,'Content-Type':'application/json'},body:JSON.stringify({action:'geocode',tenant_id:ctx.tenantId,agency_id:ctx.agencyId,address:l.address,city:l.city,state:l.state,zip:l.zip})});
 const text=await res.text();let data={};try{data=text?JSON.parse(text):{}}catch{}
 if(!res.ok||data?.success===false)throw Error(data?.error||'Unable to geocode this address.');
 const m=data.match;if(!m||!Number.isFinite(Number(m.latitude))||!Number.isFinite(Number(m.longitude)))throw Error('The geocoder did not return usable coordinates.');
 l.lat=Number(m.latitude);l.long=Number(m.longitude);l.geocodeLabel=m.label||'';l.geocodedAt=new Date().toISOString();return true;
}
async function geocodeUnmappedPermitLocations(){
 const missing=STATE.permits.locations.filter(l=>l.address&&(l.lat===null||l.lat===''||l.long===null||l.long===''||!Number.isFinite(Number(l.lat))||!Number.isFinite(Number(l.long))));
 if(!missing.length){toast('All permit locations are already mapped.');return 0}
 let ok=0,failed=0;
 for(const l of missing){try{if(await geocodePermitLocation(l))ok++}catch(error){failed++;console.warn('Permit geocoding failed for',l.id,error.message)}}
 if(ok){persist();if(typeof SuiteStore.flush==='function')await SuiteStore.flush()}
 toast(ok+' location'+(ok===1?'':'s')+' mapped'+(failed?' · '+failed+' could not be matched':'')+'.',failed>0&&ok===0);return ok;
}
