function migrateData(){if(!STATE.permits)STATE.permits=buildData();const f=buildData();Object.keys(f).forEach(k=>{if(STATE.permits[k]===undefined)STATE.permits[k]=JSON.parse(JSON.stringify(f[k]))});STATE.permits.permitTypes.forEach(t=>{if(t.active===undefined)t.active=true;if(!t.feeSchedule)t.feeSchedule=[];if(!t.requirements)t.requirements=[];if(!t.workflow)t.workflow=['Intake Review','Supervisor Review','Ready to Issue'];if(!t.customFields)t.customFields=[]});STATE.permits.applications.forEach(a=>{if(!a.history)a.history=[];if(!a.requirements)a.requirements={};if(a.feesWaived===undefined)a.feesWaived=0;if(!a.weapons)a.weapons=[];if(!a.documents)a.documents=[];if(!a.correspondence)a.correspondence=[];if(a.workflowStageIndex===undefined){const t=typeOf(a.permitTypeId),idx=(t?.workflow||[]).indexOf(a.status);a.workflowStageIndex=idx>=0?idx:-1}if(a.assignedTo===undefined)a.assignedTo='';if(a.stageStartedAt===undefined)a.stageStartedAt=a.submittedOn||fmt(new Date());if(a.stageDueDate===undefined)a.stageDueDate='';if(a.slaDays===undefined)a.slaDays=10;if(a.pendingApplicantRequest===undefined)a.pendingApplicantRequest=null;if(a.decisionReason===undefined)a.decisionReason='';if(!a.fieldValues)a.fieldValues={};if(!a.assessedFeeItems)a.assessedFeeItems=[]});if(!STATE.permits.feeAdjustments)STATE.permits.feeAdjustments=[];if(!STATE.permits.savedQueries)STATE.permits.savedQueries=[];if(!STATE.permits.renewalNotices)STATE.permits.renewalNotices=[];if(!STATE.permits.correspondenceTemplates)STATE.permits.correspondenceTemplates=[];STATE.permits.investigations.forEach(i=>{if(!i.notes)i.notes=[];if(!i.checklist)i.checklist=[];if(i.confidential===undefined)i.confidential=true});STATE.permits.locations.forEach(l=>{if(l.lat===undefined)l.lat=null;if(l.long===undefined)l.long=null});STATE.permits.inspections.forEach(i=>{if(!i.checklist)i.checklist=[];if(!i.deficiencies)i.deficiencies=[]});STATE.permits.licenses.forEach(l=>{if(!l.lifecycleHistory)l.lifecycleHistory=[]});recalcNotifications()}
function recalcNotifications(){if(!STATE.permits)return;const d=new Date(fmt(new Date())+'T00:00:00'),arr=[];STATE.permits.licenses.filter(l=>l.status==='Active'&&l.expiresOn).forEach(l=>{const days=Math.ceil((new Date(l.expiresOn+'T00:00:00')-d)/86400000);if(days>=0&&days<=60)arr.push({id:'perm_exp_'+l.id,module:'Licensing & Permits',message:l.licenseNumber+' expires in '+days+' day'+(days===1?'':'s')+'.',dueDate:l.expiresOn,readBy:[]})});STATE.permits.applications.filter(a=>workflowOverdue(a)).forEach(a=>arr.push({id:'perm_sla_'+a.id+'_'+a.status,module:'Licensing & Permits',message:a.applicationNumber+' is overdue in '+a.status+'.',dueDate:a.stageDueDate,readBy:[]}));STATE.permits.notifications=arr;window.__SUITE_NOTIFS=(window.__SUITE_NOTIFS||[]).filter(n=>n.module!=='Licensing & Permits').concat(arr)}
