function addDays(dateStr,days){const d=new Date((dateStr||fmt(new Date()))+'T12:00:00');d.setDate(d.getDate()+Number(days||0));return fmt(d)}
function workflowStages(a){return typeOf(a.permitTypeId)?.workflow||[]}
function currentWorkflowStage(a){const stages=workflowStages(a);if(a.status==='Draft')return 'Draft';if(a.status==='Awaiting Applicant')return 'Awaiting Applicant';if(a.status==='Denied')return 'Denied';if(a.status==='Withdrawn')return 'Withdrawn';if(a.status==='Issued')return 'Issued';if(a.workflowStageIndex>=0&&stages[a.workflowStageIndex])return stages[a.workflowStageIndex];return a.status||'Draft'}
function workflowDaysOpen(a){const d=a.stageStartedAt||a.submittedOn;if(!d)return 0;return Math.max(0,Math.floor((new Date(fmt(new Date())+'T00:00:00')-new Date(String(d).slice(0,10)+'T00:00:00'))/86400000))}
function workflowOverdue(a){return !!a.stageDueDate&&!['Issued','Denied','Withdrawn'].includes(a.status)&&new Date(a.stageDueDate+'T23:59:59')<new Date()}
function setWorkflowStage(a,index,note=''){const stages=workflowStages(a);if(index<0||index>=stages.length)return false;const prior=a.status||'Draft';a.workflowStageIndex=index;a.status=stages[index];a.stageStartedAt=fmt(new Date());a.stageDueDate=addDays(a.stageStartedAt,a.slaDays||10);a.pendingApplicantRequest=null;a.history.push({at:new Date().toISOString(),by:personName(CURRENT_USER_ID),action:'Workflow: '+prior+' → '+a.status+(note?' · '+note:'')});return true}
function submitApplication(a){const missingFields=validateCustomFields(a);if(missingFields.length){toast('Complete required field(s): '+missingFields.join(', '),true);return}const stages=workflowStages(a);if(!stages.length){toast('This permit type has no workflow configured.',true);return}setWorkflowStage(a,0,'Application submitted');persist();logAuditEntry('Licensing & Permits',a.applicationNumber+' submitted to '+a.status,'permits');toast('Application submitted to '+a.status+'.');openApplication(a.id)}
function advanceWorkflow(a){const stages=workflowStages(a);let idx=a.workflowStageIndex;if(a.status==='Awaiting Applicant'&&a.pendingApplicantRequest?.returnStageIndex!=null)idx=a.pendingApplicantRequest.returnStageIndex;if(idx<0)idx=stages.indexOf(a.status);const next=idx+1;if(next>=stages.length){if(a.status!=='Ready to Issue'){a.status='Ready to Issue';a.stageStartedAt=fmt(new Date());a.stageDueDate='';a.history.push({at:new Date().toISOString(),by:personName(CURRENT_USER_ID),action:'Workflow advanced to Ready to Issue'});persist();toast('Application is ready to issue.');openApplication(a.id)}return}setWorkflowStage(a,next);persist();logAuditEntry('Licensing & Permits',a.applicationNumber+' advanced to '+a.status,'permits');toast('Advanced to '+a.status+'.');openApplication(a.id)}
function requestApplicantInfo(a){const reason=prompt('What additional information is required?','');if(reason===null)return;if(!reason.trim()){toast('Enter what the applicant needs to provide.',true);return}const returnStage=a.workflowStageIndex;a.pendingApplicantRequest={requestedAt:new Date().toISOString(),requestedBy:personName(CURRENT_USER_ID),reason:reason.trim(),returnStageIndex:returnStage};const prior=a.status;a.status='Awaiting Applicant';a.stageStartedAt=fmt(new Date());a.stageDueDate='';a.history.push({at:new Date().toISOString(),by:personName(CURRENT_USER_ID),action:'Requested additional information from applicant: '+reason.trim()});persist();logAuditEntry('Licensing & Permits',a.applicationNumber+' awaiting applicant information','permits');toast('Application moved to Awaiting Applicant.');openApplication(a.id)}
function resumeAfterApplicant(a){const idx=a.pendingApplicantRequest?.returnStageIndex??Math.max(0,a.workflowStageIndex);a.pendingApplicantRequest=null;setWorkflowStage(a,idx,'Applicant information received');persist();toast('Application returned to '+a.status+'.');openApplication(a.id)}
function denyApplication(a){const reason=prompt('Denial reason:','');if(reason===null)return;if(!reason.trim()){toast('A denial reason is required.',true);return}const prior=a.status;a.status='Denied';a.decisionReason=reason.trim();a.stageDueDate='';a.history.push({at:new Date().toISOString(),by:personName(CURRENT_USER_ID),action:'Application denied from '+prior+' · '+reason.trim()});persist();logAuditEntry('Licensing & Permits',a.applicationNumber+' denied · '+reason.trim(),'permits');toast('Application denied.');openApplication(a.id)}
function assignApplication(a){const box=document.getElementById('modalBox');box.className='modal';box.innerHTML='<div class="modal-head"><h3>Assign application</h3><button class="modal-close">×</button></div><div class="modal-body"><div class="form-row"><label>Assigned staff member</label><select id="assignPermitUser">'+staffOptions(a.assignedTo)+'</select></div><div class="form-row"><label>Stage SLA (days)</label><input id="assignPermitSla" type="number" min="1" max="365" value="'+Number(a.slaDays||10)+'"></div></div><div class="modal-foot"><button id="assignPermitCancel" class="btn btn-outline">Cancel</button><button id="assignPermitSave" class="btn btn-primary">Save assignment</button></div>';SuiteUX.openModal();box.querySelector('.modal-close').onclick=box.querySelector('#assignPermitCancel').onclick=()=>openApplication(a.id);box.querySelector('#assignPermitSave').onclick=()=>{a.assignedTo=box.querySelector('#assignPermitUser').value;a.slaDays=Math.max(1,Number(box.querySelector('#assignPermitSla').value)||10);if(a.status!=='Draft'&&!['Awaiting Applicant','Denied','Withdrawn','Issued'].includes(a.status)){a.stageDueDate=addDays(a.stageStartedAt||fmt(new Date()),a.slaDays)}a.history.push({at:new Date().toISOString(),by:personName(CURRENT_USER_ID),action:'Assignment updated'+(a.assignedTo?' to '+((STATE.personnel||[]).find(p=>p.id===a.assignedTo)?.name||a.assignedTo):' to unassigned')+' · SLA '+a.slaDays+' days'});persist();toast('Assignment saved.');openApplication(a.id)}}
function workflowPanelHtml(a){const stages=workflowStages(a),assigned=(STATE.personnel||[]).find(p=>p.id===a.assignedTo)?.name||'Unassigned',stage=currentWorkflowStage(a),over=workflowOverdue(a);return '<h4>Workflow</h4><div class="quick-grid"><div><strong>Current step</strong><div>'+esc(stage)+'</div><small>'+workflowDaysOpen(a)+' day(s) in step</small></div><div><strong>Assigned to</strong><div>'+esc(assigned)+'</div><small>'+(a.stageDueDate?'Due '+esc(a.stageDueDate)+(over?' · OVERDUE':''):'No due date')+'</small></div><div><strong>What\'s next</strong><div>'+esc(a.status==='Draft'?(stages[0]||'No workflow configured'):a.status==='Awaiting Applicant'?'Applicant response required':a.workflowStageIndex>=0&&stages[a.workflowStageIndex+1]?stages[a.workflowStageIndex+1]:a.status==='Ready to Issue'?'Issue license':'Ready to Issue')+'</div></div></div>'+(a.pendingApplicantRequest?'<div class="callout callout-yellow" style="margin-top:10px"><strong>Waiting on applicant</strong><div style="margin-top:5px">'+esc(a.pendingApplicantRequest.reason)+'</div></div>':'')+'<div style="display:flex;gap:6px;flex-wrap:wrap;margin-top:10px">'+stages.map((s,i)=>'<span class="badge '+(i===a.workflowStageIndex?'badge-assigned':i<a.workflowStageIndex?'badge-available':'badge-role')+'">'+esc(s)+'</span>').join('')+'</div>'}
function appRow(a){const t=typeOf(a.permitTypeId),p=applicant(a.applicantId),l=locationOf(a.locationId),assigned=(STATE.personnel||[]).find(x=>x.id===a.assignedTo)?.name||'Unassigned',over=workflowOverdue(a);return '<tr><td><button class="link-btn permit-record-chip" data-papp="'+a.id+'">'+esc(a.applicationNumber)+'</button></td><td>'+esc(t?.name||'')+'</td><td>'+esc(p?.name||'')+'</td><td>'+esc(l?.address||'')+'</td><td><span class="badge '+(over?'badge-missing':'badge-role')+'">'+esc(a.status)+(over?' · overdue':'')+'</span></td><td>'+esc(assigned)+'</td><td>'+esc(a.stageDueDate||'—')+'</td><td>'+cash(balance(a))+'</td></tr>'}
function bindApps(root){root.querySelectorAll('[data-papp]').forEach(b=>b.onclick=()=>openApplication(b.dataset.papp))}
function applicationHaystack(a){const p=applicant(a.applicantId),l=locationOf(a.locationId),t=typeOf(a.permitTypeId);return [a.applicationNumber,a.applicationType,a.status,a.notes,t?.name,t?.category,p?.name,p?.email,p?.phone,p?.address,...(p?.aliases||[]),l?.address,l?.city,l?.state,l?.zip,l?.parcel,l?.notes,...(a.weapons||[]).flatMap(w=>[w.make,w.model,w.caliber,w.serial])].join(' ').toLowerCase()}
function advancedSearchModal(){const box=document.getElementById('modalBox');box.className='modal modal-xl';const saved=STATE.permits.savedQueries||[];box.innerHTML='<div class="modal-head"><h3>Advanced Licensing & Permits Search</h3><button class="modal-close">×</button></div><div class="modal-body"><div class="quick-grid"><div class="form-row"><label>Keywords / relationship search</label><input id="asText" placeholder="Name, alias, business, permit #, address, phone, email, firearm serial..."></div><div class="form-row"><label>Permit type</label><select id="asType"><option value="">Any type</option>'+STATE.permits.permitTypes.slice().sort((a,b)=>a.name.localeCompare(b.name)).map(t=>'<option value="'+t.id+'">'+esc(t.name)+'</option>').join('')+'</select></div><div class="form-row"><label>Status</label><select id="asStatus"><option value="">Any status</option>'+STATUSES.map(s=>'<option>'+s+'</option>').join('')+'</select></div></div><div class="quick-grid"><div class="form-row"><label>Submitted from</label><input id="asFrom" type="date"></div><div class="form-row"><label>Submitted through</label><input id="asTo" type="date"></div><div class="form-row"><label>Balance</label><select id="asBalance"><option value="">Any balance</option><option value="due">Balance due</option><option value="paid">Paid in full</option></select></div></div><div style="display:flex;gap:8px;align-items:end"><div class="form-row" style="flex:1"><label>Saved search name</label><input id="asSaveName" placeholder="e.g. CCW pending over 30 days"></div><button id="asSave" class="btn btn-outline">Save search</button></div>'+(saved.length?'<div class="form-row"><label>Saved searches</label><select id="asSaved"><option value="">Choose saved search...</option>'+saved.map((q,i)=>'<option value="'+i+'">'+esc(q.name)+'</option>').join('')+'</select></div>':'')+'<div id="asResults" style="margin-top:16px"></div></div><div class="modal-foot"><button class="btn btn-outline" id="asClose">Close</button><button class="btn btn-primary" id="asRun">Run search</button></div>';SuiteUX.openModal();const close=()=>SuiteUX.closeModal();box.querySelector('.modal-close').onclick=box.querySelector('#asClose').onclick=close;const criteria=()=>({text:box.querySelector('#asText').value.trim(),type:box.querySelector('#asType').value,status:box.querySelector('#asStatus').value,from:box.querySelector('#asFrom').value,to:box.querySelector('#asTo').value,balance:box.querySelector('#asBalance').value});const apply=q=>{box.querySelector('#asText').value=q.text||'';box.querySelector('#asType').value=q.type||'';box.querySelector('#asStatus').value=q.status||'';box.querySelector('#asFrom').value=q.from||'';box.querySelector('#asTo').value=q.to||'';box.querySelector('#asBalance').value=q.balance||'';};box.querySelector('#asSaved')?.addEventListener('change',e=>{if(e.target.value!=='')apply(saved[Number(e.target.value)].criteria)});const run=()=>{const q=criteria(),needle=q.text.toLowerCase();const rows=STATE.permits.applications.filter(a=>(!needle||applicationHaystack(a).includes(needle))&&(!q.type||a.permitTypeId===q.type)&&(!q.status||a.status===q.status)&&(!q.from||a.submittedOn>=q.from)&&(!q.to||a.submittedOn<=q.to)&&(!q.balance||(q.balance==='due'?balance(a)>0:balance(a)<=0)));box.querySelector('#asResults').innerHTML='<div class="hint" style="margin-bottom:8px">'+rows.length+' matching application'+(rows.length===1?'':'s')+'</div><table><thead><tr><th>Application</th><th>Type</th><th>Applicant</th><th>Location</th><th>Status</th><th>Assigned</th><th>Due</th><th>Balance</th></tr></thead><tbody>'+rows.map(appRow).join('')+'</tbody></table>';bindApps(box)};box.querySelector('#asRun').onclick=run;box.querySelector('#asSave').onclick=()=>{const name=box.querySelector('#asSaveName').value.trim();if(!name){toast('Enter a saved search name.',true);return}STATE.permits.savedQueries=[{id:uid('query'),name,criteria:criteria()},...(STATE.permits.savedQueries||[]).filter(x=>x.name!==name)].slice(0,25);persist();toast('Search saved.');advancedSearchModal()};run()}
function feeAdjustmentModal(a){const box=document.getElementById('modalBox');box.className='modal';box.innerHTML='<div class="modal-head"><h3>Fee adjustment · '+esc(a.applicationNumber)+'</h3><button class="modal-close">×</button></div><div class="modal-body"><div class="form-row"><label>Adjustment type</label><select id="faType"><option>Additional charge</option><option>Waiver</option><option>Refund</option><option>Credit</option></select></div><div class="form-row"><label>Amount</label><input id="faAmount" type="number" min="0" step="0.01"></div><div class="form-row"><label>Reason</label><textarea id="faReason" rows="3"></textarea></div><p class="field-error" id="faErr"></p></div><div class="modal-foot"><button class="btn btn-outline" id="faCancel">Cancel</button><button class="btn btn-primary" id="faSave">Apply</button></div>';SuiteUX.openModal();box.querySelector('.modal-close').onclick=box.querySelector('#faCancel').onclick=()=>openApplication(a.id);box.querySelector('#faSave').onclick=()=>{const type=box.querySelector('#faType').value,n=Number(box.querySelector('#faAmount').value),reason=box.querySelector('#faReason').value.trim();if(!(n>0)||!reason){box.querySelector('#faErr').textContent='Amount and reason are required.';return}if(type==='Additional charge')a.feesAssessed=Number(a.feesAssessed||0)+n;else if(type==='Waiver'||type==='Credit')a.feesWaived=Number(a.feesWaived||0)+n;else if(type==='Refund')a.feesPaid=Math.max(0,Number(a.feesPaid||0)-n);STATE.permits.feeAdjustments.push({id:uid('adj'),applicationId:a.id,type,amount:n,reason,date:fmt(new Date()),by:personName(CURRENT_USER_ID)});a.history.push({at:new Date().toISOString(),by:personName(CURRENT_USER_ID),action:type+' '+cash(n)+' · '+reason});persist();toast('Fee adjustment applied.');openApplication(a.id)}}
function ccwWeaponsHtml(a){if(a.permitTypeId!=='ccw')return '';return '<h4>CCW firearms</h4><div id="ccwWeapons">'+((a.weapons||[]).map((w,i)=>'<div class="readiness-line"><div><strong>'+esc([w.make,w.model].filter(Boolean).join(' ')||'Firearm')+'</strong><br><small>'+esc(w.caliber||'')+(w.serial?' · Serial '+esc(w.serial):'')+'</small></div>'+(can('permits_edit')?'<button class="btn btn-outline btn-sm" data-del-weapon="'+i+'">Remove</button>':'')+'</div>').join('')||'<div class="hint">No firearms entered.</div>')+'</div>'+(can('permits_edit')?'<button id="addWeapon" class="btn btn-outline btn-sm" style="margin-top:8px">Add firearm</button>':'')}
function applicationDocumentsHtml(a){const docs=a.documents||[];return '<h4>Documents & attachments</h4>'+(can('permits_edit')?'<div style="display:flex;gap:8px;align-items:center;margin-bottom:10px"><input id="permDocInput" type="file"><button id="permDocUpload" class="btn btn-outline btn-sm">Upload to AWS</button></div>':'')+'<table><thead><tr><th>File</th><th>Uploaded</th><th>Size</th><th></th></tr></thead><tbody>'+(docs.map((d,i)=>'<tr><td>'+esc(d.filename||'Document')+'</td><td>'+esc(d.uploadedDate||'')+' by '+esc(d.uploadedBy||'')+'</td><td>'+esc(d.sizeKb||'')+' KB</td><td><button class="btn btn-outline btn-sm" data-perm-doc-open="'+i+'">Open</button>'+(can('permits_edit')?' <button class="btn btn-outline btn-sm" data-perm-doc-remove="'+i+'">Remove</button>':'')+'</td></tr>').join('')||'<tr><td colspan="4">No documents attached.</td></tr>')+'</tbody></table>'}
function correspondenceHtml(a){const rows=(a.correspondence||[]).slice().reverse();return '<h4>Correspondence</h4><div style="display:flex;gap:8px;margin-bottom:10px">'+(can('permits_edit')?'<button class="btn btn-outline btn-sm" id="permCompose">Compose correspondence</button>':'')+'</div>'+(rows.map(x=>'<div class="readiness-line"><div><strong>'+esc(x.subject||x.templateName||'Correspondence')+'</strong><br><small>'+esc(x.at||'')+' · '+esc(x.by||'')+' · '+esc(x.channel||'Prepared')+'</small><div>'+esc(x.body||'')+'</div></div></div>').join('')||'<div class="hint">No correspondence recorded.</div>')}
function composeCorrespondence(a){const p=applicant(a.applicantId),box=document.getElementById('modalBox'),templates=STATE.permits.correspondenceTemplates||[];box.className='modal modal-lg';box.innerHTML='<div class="modal-head"><h3>Compose correspondence · '+esc(a.applicationNumber)+'</h3><button class="modal-close">×</button></div><div class="modal-body"><div class="form-row"><label>Template</label><select id="corTemplate"><option value="">Custom</option>'+templates.map(t=>'<option value="'+t.id+'">'+esc(t.name)+'</option>').join('')+'</select></div><div class="form-row"><label>To</label><input id="corTo" value="'+esc(p?.email||'')+'"></div><div class="form-row"><label>Subject</label><input id="corSubject"></div><div class="form-row"><label>Message / letter body</label><textarea id="corBody" rows="10"></textarea></div></div><div class="modal-foot"><button id="corCancel" class="btn btn-outline">Cancel</button><button id="corLetter" class="btn btn-outline">Generate letter</button><button id="corEmail" class="btn btn-primary">Prepare email</button></div>';SuiteUX.openModal();box.querySelector('.modal-close').onclick=box.querySelector('#corCancel').onclick=()=>openApplication(a.id);box.querySelector('#corTemplate').onchange=e=>{const t=templates.find(x=>x.id===e.target.value);if(t){box.querySelector('#corSubject').value=t.subject||'';box.querySelector('#corBody').value=t.body||''}};const record=channel=>{const item={id:uid('cor'),at:new Date().toISOString(),by:personName(CURRENT_USER_ID),channel,to:box.querySelector('#corTo').value.trim(),subject:box.querySelector('#corSubject').value.trim(),body:box.querySelector('#corBody').value.trim(),templateName:templates.find(x=>x.id===box.querySelector('#corTemplate').value)?.name||'Custom'};a.correspondence=a.correspondence||[];a.correspondence.push(item);a.history.push({at:item.at,by:item.by,action:channel+' correspondence prepared: '+item.subject});persist();return item};box.querySelector('#corEmail').onclick=()=>{const item=record('Email');location.href='mailto:'+encodeURIComponent(item.to)+'?subject='+encodeURIComponent(item.subject)+'&body='+encodeURIComponent(item.body);setTimeout(()=>openApplication(a.id),200)};box.querySelector('#corLetter').onclick=()=>{const item=record('Letter'),agency=STATE.agencyBranding?.title||'SonoMarzi Agency',w=window.open('','_blank');if(w){w.document.write('<!doctype html><html><head><title>'+esc(item.subject)+'</title><style>body{font-family:Arial,sans-serif;margin:48px;line-height:1.5}.head{text-align:center;margin-bottom:40px}.body{white-space:pre-wrap}.sig{margin-top:40px}</style></head><body><div class="head"><h2>'+esc(agency)+'</h2></div><p>'+esc(new Date().toLocaleDateString())+'</p><p>'+esc(applicant(a.applicantId)?.name||'')+'<br>'+esc(applicant(a.applicantId)?.address||'')+'</p><p><strong>'+esc(item.subject)+'</strong></p><div class="body">'+esc(item.body)+'</div><div class="sig">Sincerely,<br>'+esc(personName(CURRENT_USER_ID))+'</div><script>window.print()<\/script></body></html>');w.document.close()}else toast('Pop-up blocked.',true);setTimeout(()=>openApplication(a.id),200)}}
function applicantModal(idv){const p=applicant(idv);if(!p)return;const apps=STATE.permits.applications.filter(a=>a.applicantId===p.id),lics=STATE.permits.licenses.filter(l=>l.applicantId===p.id),box=document.getElementById('modalBox');box.className='modal modal-xl';box.innerHTML='<div class="modal-head"><div><h3>'+esc(p.name)+'</h3><div class="hint">'+esc(p.type||'Applicant')+'</div></div><button class="modal-close">×</button></div><div class="modal-body"><div class="quick-grid"><div><strong>Email</strong><div>'+esc(p.email||'—')+'</div></div><div><strong>Phone</strong><div>'+esc(p.phone||'—')+'</div></div><div><strong>Address</strong><div>'+esc(p.address||'—')+'</div></div></div><div class="form-row"><label>Aliases / DBA names</label><textarea id="apAliases" '+(can('permits_edit')?'':'readonly')+'>'+esc((p.aliases||[]).join('\n'))+'</textarea></div><div class="form-row"><label>Notes</label><textarea id="apNotes" '+(can('permits_edit')?'':'readonly')+'>'+esc(p.notes||'')+'</textarea></div><h4>Applications</h4><table><thead><tr><th>Application</th><th>Type</th><th>Status</th><th>Submitted</th></tr></thead><tbody>'+apps.map(a=>'<tr><td><button class="link-btn permit-record-chip" data-related-app="'+a.id+'">'+esc(a.applicationNumber)+'</button></td><td>'+esc(typeOf(a.permitTypeId)?.name||'')+'</td><td>'+esc(a.status)+'</td><td>'+esc(a.submittedOn)+'</td></tr>').join('')+'</tbody></table><h4>Licenses & permits</h4><table><thead><tr><th>License</th><th>Type</th><th>Status</th><th>Expires</th></tr></thead><tbody>'+lics.map(l=>'<tr><td><button class="link-btn permit-record-chip" data-related-lic="'+l.id+'">'+esc(l.licenseNumber)+'</button></td><td>'+esc(typeOf(l.permitTypeId)?.name||'')+'</td><td>'+esc(l.status)+'</td><td>'+esc(l.expiresOn||'—')+'</td></tr>').join('')+'</tbody></table></div><div class="modal-foot"><button id="apClose" class="btn btn-outline">Close</button>'+(can('permits_edit')?'<button id="apSave" class="btn btn-primary">Save applicant</button>':'')+'</div>';SuiteUX.openModal();box.querySelector('.modal-close').onclick=box.querySelector('#apClose').onclick=()=>SuiteUX.closeModal();box.querySelector('#apSave')?.addEventListener('click',()=>{p.aliases=box.querySelector('#apAliases').value.split('\n').map(x=>x.trim()).filter(Boolean);p.notes=box.querySelector('#apNotes').value.trim();persist();toast('Applicant saved.');applicantModal(p.id)});box.querySelectorAll('[data-related-app]').forEach(b=>b.onclick=()=>openApplication(b.dataset.relatedApp));box.querySelectorAll('[data-related-lic]').forEach(b=>b.onclick=()=>openLicense(b.dataset.relatedLic))}
function locationModal(idv){const l=locationOf(idv);if(!l)return;const apps=STATE.permits.applications.filter(a=>a.locationId===l.id),lics=STATE.permits.licenses.filter(x=>x.locationId===l.id),ins=STATE.permits.inspections.filter(i=>application(i.applicationId)?.locationId===l.id),box=document.getElementById('modalBox');box.className='modal modal-xl';box.innerHTML='<div class="modal-head"><h3>'+esc(l.address)+'</h3><button class="modal-close">×</button></div><div class="modal-body"><p>'+esc([l.city,l.state,l.zip].filter(Boolean).join(', '))+'</p><div class="form-row"><label>Parcel / APN</label><input id="locParcel" value="'+esc(l.parcel||'')+'" '+(can('permits_edit')?'':'readonly')+'></div><div class="quick-grid"><div class="form-row"><label>Latitude</label><input id="locLat" type="number" step="any" value="'+esc(l.lat??'')+'" '+(can('permits_edit')?'':'readonly')+'></div><div class="form-row"><label>Longitude</label><input id="locLong" type="number" step="any" value="'+esc(l.long??'')+'" '+(can('permits_edit')?'':'readonly')+'></div></div><div class="form-row"><label>Location notes</label><textarea id="locNotes" '+(can('permits_edit')?'':'readonly')+'>'+esc(l.notes||'')+'</textarea></div><div class="work-metrics">'+metric('Applications',apps.length,'At this location')+metric('Licenses',lics.length,'All statuses')+metric('Inspections',ins.length,'Recorded inspections')+'</div><h4>Related applications</h4>'+apps.map(a=>'<div class="readiness-line"><div><strong>'+esc(a.applicationNumber)+'</strong><br><small>'+esc(typeOf(a.permitTypeId)?.name||'')+' · '+esc(a.status)+'</small></div><button class="btn btn-outline btn-sm" data-related-app="'+a.id+'">Open</button></div>').join('')+'</div><div class="modal-foot"><button id="locClose" class="btn btn-outline">Close</button>'+(can('permits_edit')?'<button id="locSave" class="btn btn-primary">Save location</button>':'')+'</div>';SuiteUX.openModal();box.querySelector('.modal-close').onclick=box.querySelector('#locClose').onclick=()=>SuiteUX.closeModal();box.querySelector('#locSave')?.addEventListener('click',()=>{l.parcel=box.querySelector('#locParcel').value.trim();l.lat=box.querySelector('#locLat').value===''?null:Number(box.querySelector('#locLat').value);l.long=box.querySelector('#locLong').value===''?null:Number(box.querySelector('#locLong').value);l.notes=box.querySelector('#locNotes').value.trim();persist();toast('Location saved.');locationModal(l.id)});box.querySelectorAll('[data-related-app]').forEach(b=>b.onclick=()=>openApplication(b.dataset.relatedApp))}
function inspectionReportHtml(i){const a=application(i.applicationId),p=applicant(a?.applicantId),l=locationOf(a?.locationId),agency=STATE.agencyBranding?.title||'SonoMarzi Agency';return '<!doctype html><html><head><title>Inspection '+esc(a?.applicationNumber||'')+'</title><style>body{font-family:Arial,sans-serif;margin:40px}.head{text-align:center;border-bottom:2px solid #111;padding-bottom:14px;margin-bottom:24px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.label{font-size:11px;text-transform:uppercase;color:#555}.value{font-weight:700}.section{margin-top:24px}.item{padding:6px 0;border-bottom:1px solid #ddd}@media print{body{margin:18px}}</style></head><body><div class="head"><h2>'+esc(agency)+'</h2><h3>License / Permit Inspection Report</h3></div><div class="grid"><div><div class="label">Application</div><div class="value">'+esc(a?.applicationNumber||'')+'</div></div><div><div class="label">Permit type</div><div class="value">'+esc(typeOf(a?.permitTypeId)?.name||'')+'</div></div><div><div class="label">Applicant</div><div class="value">'+esc(p?.name||'')+'</div></div><div><div class="label">Location</div><div class="value">'+esc(l?l.address+', '+l.city+', '+l.state+' '+l.zip:'')+'</div></div><div><div class="label">Inspection</div><div class="value">'+esc(i.type||'')+'</div></div><div><div class="label">Scheduled / completed</div><div class="value">'+esc(i.scheduledOn||'')+'</div></div><div><div class="label">Status</div><div class="value">'+esc(i.status||'')+'</div></div><div><div class="label">Result</div><div class="value">'+esc(i.result||'Pending')+'</div></div></div><div class="section"><h4>Checklist</h4>'+((i.checklist||[]).map(x=>'<div class="item">'+esc(x)+'</div>').join('')||'<div>None</div>')+'</div><div class="section"><h4>Deficiencies / corrective actions</h4>'+((i.deficiencies||[]).map(x=>'<div class="item">'+esc(x)+'</div>').join('')||'<div>None</div>')+'</div><div class="section"><h4>Inspector notes</h4><div>'+esc(i.notes||'None')+'</div></div><script>window.print()<\/script></body></html>'}
function metric(label,value,hint){return '<div class="work-metric"><span>'+esc(label)+'</span><strong>'+esc(String(value))+'</strong><small>'+esc(hint||'')+'</small></div>'}
function expiryDays(l){const today=new Date(fmt(new Date())+'T00:00:00'),end=new Date(l.expiresOn+'T00:00:00');return Math.ceil((end-today)/86400000)}
function expiryMetric(label,value,hint,tone,days){return '<button type="button" class="work-metric permit-expiry-metric" data-expiry-window="'+days+'" style="text-align:left;cursor:pointer;border:2px solid '+tone+';background:color-mix(in srgb, '+tone+' 8%, var(--panel));"><span>'+esc(label)+'</span><strong>'+esc(String(value))+'</strong><small>'+esc(hint||'')+'</small></button>'}
let RENEWAL_WINDOW=0;
function renewalNoticeBody(l){const p=applicant(l.applicantId),t=typeOf(l.permitTypeId),tpl=(STATE.permits.correspondenceTemplates||[]).find(x=>x.id==='renewal_due');return (tpl?.body||'Your license or permit will expire soon. Please submit your renewal application before the expiration date.')+'\n\nLicense / Permit: '+l.licenseNumber+'\nType: '+(t?.name||'')+'\nExpiration date: '+l.expiresOn+'\nHolder: '+(p?.name||'')}
function recordRenewalNotice(l,method,status){const p=applicant(l.applicantId),tpl=(STATE.permits.correspondenceTemplates||[]).find(x=>x.id==='renewal_due'),n={id:uid('rn'),licenseId:l.id,licenseNumber:l.licenseNumber,createdAt:new Date().toISOString(),createdBy:personName(CURRENT_USER_ID),method,status,recipient:p?.email||'',subject:tpl?.subject||'License / permit renewal notice',body:renewalNoticeBody(l)};STATE.permits.renewalNotices.push(n);l.lifecycleHistory=l.lifecycleHistory||[];l.lifecycleHistory.push({at:n.createdAt,by:n.createdBy,from:l.status,to:l.status,reason:'Renewal notice '+status.toLowerCase()+' via '+method});persist();logAuditEntry('Licensing & Permits',l.licenseNumber+' renewal notice '+status.toLowerCase()+' via '+method,'permits');return n}
