function issue(a){const t=typeOf(a.permitTypeId);if(a.status!=='Ready to Issue'){toast('Application must be Ready to Issue before a license can be issued.',true);return}if(balance(a)>0&&!confirm('Outstanding balance '+cash(balance(a))+'. Issue anyway?'))return;const missing=Object.entries(a.requirements||{}).filter(([,v])=>!v).map(([k])=>k);if(missing.length&&!confirm('Incomplete requirements:\n\n'+missing.join('\n')+'\n\nIssue anyway?'))return;const issued=fmt(new Date()),exp=t.renewalMonths?(()=>{const d=new Date(issued+'T12:00:00');d.setMonth(d.getMonth()+t.renewalMonths);return fmt(d)})():'';STATE.permits.licenses.push({id:uid('lic'),licenseNumber:a.applicationNumber,permitTypeId:a.permitTypeId,applicantId:a.applicantId,locationId:a.locationId,applicationId:a.id,issuedOn:issued,expiresOn:exp,status:'Active',conditions:'',issuedBy:personName(CURRENT_USER_ID),verificationCode:crypto.randomUUID().replace(/-/g,'').slice(0,12).toUpperCase(),fieldSnapshot:JSON.parse(JSON.stringify(a.fieldValues||{})),feeSnapshot:JSON.parse(JSON.stringify(a.assessedFeeItems||[]))});a.status='Issued';persist();SuiteUX.closeModal();renderLicenses()}
function licenseDoc(l){const t=typeOf(l.permitTypeId),p=applicant(l.applicantId),x=locationOf(l.locationId),b=STATE.agencyBranding||{},tpl=STATE.permits.templates.license;return '<!doctype html><html><head><meta charset="utf-8"><title>'+esc(l.licenseNumber)+'</title><style>body{font-family:Arial;color:#111;margin:36px}.card{border:3px solid #111;padding:30px;max-width:760px;margin:auto}.center{text-align:center}.grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}.lab{font-size:11px;text-transform:uppercase;color:#555}.val{font-size:16px;font-weight:700}.foot{margin-top:30px;border-top:1px solid #777;padding-top:12px;font-size:11px}@media print{button{display:none}body{margin:0}}</style></head><body><button onclick="window.print()">Print / Save PDF</button><div class="card"><div class="center"><h1>'+esc(b.title||'Issuing Agency')+'</h1><h2>'+esc(tpl.title)+'</h2></div><div class="grid"><div><div class="lab">License / Permit</div><div class="val">'+esc(t?.name||'')+'</div></div><div><div class="lab">Number</div><div class="val">'+esc(l.licenseNumber)+'</div></div><div><div class="lab">Holder</div><div class="val">'+esc(p?.name||'')+'</div></div><div><div class="lab">Status</div><div class="val">'+esc(l.status)+'</div></div><div><div class="lab">Location</div><div class="val">'+esc(x?(x.address+', '+x.city+', '+x.state+' '+x.zip):'')+'</div></div><div><div class="lab">Issued By</div><div class="val">'+esc(l.issuedBy||'')+'</div></div><div><div class="lab">Issue Date</div><div class="val">'+esc(l.issuedOn)+'</div></div><div><div class="lab">Expiration</div><div class="val">'+esc(l.expiresOn||'No fixed expiration')+'</div></div></div>'+(l.conditions?'<p><strong>Conditions:</strong> '+esc(l.conditions)+'</p>':'')+'<div class="foot">Verification code: '+esc(l.verificationCode||'Legacy credential')+'<br>'+esc(tpl.footer)+'</div></div></body></html>'}
function openLicense(id){const l=STATE.permits.licenses.find(x=>x.id===id);if(!l)return;const box=document.getElementById('modalBox'),p=applicant(l.applicantId),t=typeOf(l.permitTypeId);box.className='modal modal-lg';box.innerHTML='<div class="modal-head"><h3>'+esc(l.licenseNumber)+'</h3><button class="modal-close">×</button></div><div class="modal-body"><p><strong>'+esc(t?.name||'')+'</strong> · '+esc(p?.name||'')+'</p><p>Status: '+esc(l.status)+' · Issued '+esc(l.issuedOn)+' · Expires '+esc(l.expiresOn||'No fixed expiration')+'</p><div class="form-row"><label>Conditions / restrictions</label><textarea id="lCond" '+(can('permits_issue')?'':'readonly')+'>'+esc(l.conditions||'')+'</textarea></div></div><div class="panel" style="margin-top:16px"><div class="panel-head"><h4>Renewal notice history</h4></div><div class="panel-body">'+((STATE.permits.renewalNotices||[]).filter(n=>n.licenseId===l.id).sort((a,b)=>b.createdAt.localeCompare(a.createdAt)).map(n=>'<div class="readiness-line"><div><strong>'+esc(n.method)+' · '+esc(n.status)+'</strong><br><small>'+esc(new Date(n.createdAt).toLocaleString())+' · '+esc(n.createdBy)+(n.recipient?' · '+esc(n.recipient):'')+'</small></div></div>').join('')||'<div class="hint">No renewal notices recorded.</div>')+'</div></div><div class="modal-foot"><button class="btn btn-outline" id="lClose">Close</button><button class="btn btn-outline" id="lExport">Export license</button><button class="btn btn-outline" id="lPrint">Print / PDF</button><button class="btn btn-outline" id="lRenewPrint">Print Renewal Notice</button><button class="btn btn-primary" id="lRenewEmail">Email Renewal Notice</button></div>';SuiteUX.openModal();box.querySelector('.modal-close').onclick=box.querySelector('#lClose').onclick=()=>SuiteUX.closeModal();box.querySelector('#lExport').onclick=()=>{const blob=new Blob([licenseDoc(l)],{type:'text/html'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=l.licenseNumber+'.html';a.click();setTimeout(()=>URL.revokeObjectURL(url),500)};box.querySelector('#lPrint').onclick=()=>{const w=window.open('','_blank');if(w){w.document.write(licenseDoc(l));w.document.close()}else toast('Pop-up blocked.',true)};box.querySelector('#lRenewPrint').onclick=()=>printRenewalNotice(l);box.querySelector('#lRenewEmail').onclick=()=>emailRenewalNotice(l);if(can('permits_issue')){box.querySelector('#lCond').onchange=()=>{l.conditions=box.querySelector('#lCond').value.trim();persist()};const foot=box.querySelector('.modal-foot');if(l.status==='Active'){const s=document.createElement('button');s.className='btn btn-outline';s.textContent='Suspend';s.onclick=()=>setLicenseStatus(l,'Suspended');foot.append(s);const r=document.createElement('button');r.className='btn btn-outline';r.textContent='Revoke';r.onclick=()=>setLicenseStatus(l,'Revoked');foot.append(r)}else if(['Suspended','Revoked'].includes(l.status)){const x=document.createElement('button');x.className='btn btn-outline';x.textContent='Reinstate';x.onclick=()=>setLicenseStatus(l,'Active');foot.append(x)}if(l.expiresOn&&can('permits_create')){const n=document.createElement('button');n.className='btn btn-outline';n.textContent='Start renewal';n.onclick=()=>initiateRenewal(l.id);foot.append(n)}}}
